import os
from google import genai

def get_embeddings_client(api_key: str = None):
    """Initializes and returns a Google Generative AI client for embeddings."""
    api_key = api_key or os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise ValueError("Google API Key not found. Please set GOOGLE_API_KEY environment variable or pass it directly.")
    return genai.Client(api_key=api_key)

from dataclasses import dataclass
from typing import List, Dict, Any

@dataclass
class EmbeddingsRequest:
    texts: List[str]

@dataclass
class EmbeddingResponse:
    embedding: List[float]

@dataclass
class BatchEmbeddingsResponse:
    embeddings: List[List[float]]

def normalize_embedding_response(genai_response: Any) -> EmbeddingResponse:
    """Normalizes the genai client's embedding response."""
    # Assuming genai_response.embeddings[0].values is the structure for single embedding
    return EmbeddingResponse(embedding=list(genai_response.embeddings[0].values))

def normalize_batch_embedding_response(genai_response: Any) -> BatchEmbeddingsResponse:
    """Normalizes the genai client's batch embedding response."""
    # Assuming genai_response.embeddings is a list of embedding objects
    return BatchEmbeddingsResponse(embeddings=[list(e.values) for e in genai_response.embeddings])

from typing import List, Dict, Any

from embeddings_client import get_embeddings_client
from embeddings_models import EmbeddingsRequest, BatchEmbeddingsResponse, normalize_batch_embedding_response

def embed_batch(payload: Dict[str, Any], config: Dict[str, Any] = None) -> Dict[str, Any]:
    config = config or {}
    texts_to_embed = payload.get("texts", [])
    if not texts_to_embed:
        raise ValueError("Payload must contain a 'texts' key with a list of strings.")

    client = get_embeddings_client(api_key=config.get("api_key"))

    # The genai client's embed_content method expects 'contents' as a list of strings
    response = client.models.embed_content(model="gemini-embedding-001", contents=texts_to_embed)

    normalized_response = normalize_batch_embedding_response(response)
    return {"embeddings": normalized_response.embeddings}

import os
from typing import List, Dict, Any
from google import genai

def embedding_job_summary(payload: Dict[str, Any], config: Dict[str, Any] = None) -> Dict[str, str]:
    config = config or {}
    embedding_results = payload.get("embedding_results") # Expects a list of dicts with 'text' and 'embedding'

    if not embedding_results:
        raise ValueError("Payload must contain 'embedding_results'.")

    api_key = config.get("api_key") or os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise ValueError("Google API Key not found. Please set GOOGLE_API_KEY environment variable or pass it directly.")

    model_name = "gemini-pro" # Using a generative model for summarization

    with genai.Client(api_key=api_key) as client:
        model = client.models.get(model_name)

        # Prepare content for summarization
        texts = [item["text"] for item in embedding_results if "text" in item]
        if not texts:
            return {"summary": "No texts provided for summarization."}

        prompt = "Summarize the following texts, which were part of an embedding job:\n\n" + "\n---\n".join(texts)

        response = model.generate_content(prompt)
        summary_text = response.candidates[0].content.parts[0].text

    return {"summary": summary_text}
